    const start = { x: 0, y: 0, width: 100, height: 50, rotation: 90 };
    const next = resizeBox({
      start,
      handle: "e",
      pointer: { x: 50, y: 95 },
      shift: false,
      alt: false,
    });
    expect(next.width).toBeCloseTo(120);
    expect(next.height).toBeCloseTo(50);
    expect(next.rotation).toBeCloseTo(90);
