    const right = apply(m, next.width, next.height / 2);
    expect(right.x).toBeCloseTo(50);
    expect(right.y).toBeCloseTo(95);
    const left = apply(m, 0, next.height / 2);
    expect(left.x).toBeCloseTo(50);
    expect(left.y).toBeCloseTo(-25);
  });

