    expect(next.x).toBeCloseTo(0);
    expect(next.y).toBeCloseTo(0);
  });
});

describe("aabb", () => {
  it("detects overlap", () => {
    expect(intersects({ x: 0, y: 0, width: 10, height: 10 }, { x: 9, y: 9, width: 2, height: 2 })).toBe(
