  itemSpacing: 10,
  padding: [0, 0, 0, 0] as [number, number, number, number],
  primaryAlign: "start" as const,
  counterAlign: "start" as const,
  primarySizing: "fixed" as const,
  counterSizing: "fixed" as const,
};

export function createCanvas(): SceneNode {
  return {
