import type { TextNode } from "../types";

let measureCtx: CanvasRenderingContext2D | null = null;

function context(): CanvasRenderingContext2D | null {
  if (measureCtx) return measureCtx;
  if (typeof document === "undefined") return null;
  const canvas = document.createElement("canvas");
  measureCtx = canvas.getContext("2d");
  return measureCtx;
}

export function fontCss(node: Pick<TextNode, "fontWeight" | "fontSize" | "fontFamily">): string {
  return `${node.fontWeight} ${node.fontSize}px "${node.fontFamily}"`;
}

export function ensureFont(node: Pick<TextNode, "fontWeight" | "fontSize" | "fontFamily">): void {
  if (typeof document === "undefined" || !document.fonts) return;
  void document.fonts.load(fontCss(node));
}

export function measureText(node: TextNode, maxWidth: number | null): { width: number; height: number } {
  const lines = wrapText(node, maxWidth);
  let width = 0;
  for (const line of lines) width = Math.max(width, measureLine(node, line));
  const height = Math.max(node.lineHeight, lines.length * node.lineHeight);
  return { width: Math.max(1, width), height };
}

export function wrapText(node: TextNode, maxWidth: number | null): string[] {
  const paragraphs = node.text.split("\n");
  if (maxWidth === null) return paragraphs.length ? paragraphs : [""];
  const lines: string[] = [];
  for (const paragraph of paragraphs) {
    const words = paragraph.split(/(\s+)/);
    let current = "";
    for (const word of words) {
      const next = current + word;
      if (current && measureLine(node, next) > maxWidth) {
        lines.push(current.replace(/\s+$/, ""));
        current = word.trimStart();
      } else {
        current = next;
      }
    }
    lines.push(current);
  }
  return lines.length ? lines : [""];
}

export function measureLine(node: TextNode, line: string): number {
  const ctx = context();
  if (!ctx) return estimate(node, line);
  ctx.font = fontCss(node);
  if (node.letterSpacing === 0) return ctx.measureText(line).width;
  let width = 0;
  for (const ch of line) width += ctx.measureText(ch).width + node.letterSpacing;
  return Math.max(0, width - (line.length ? node.letterSpacing : 0));
}

function estimate(node: TextNode, line: string): number {
  const factor = node.fontFamily.includes("Mono") ? 0.62 : 0.52;
  return line.length * node.fontSize * factor + Math.max(0, line.length - 1) * node.letterSpacing;
}

export function preloadCanvasFonts(): void {
  if (typeof document === "undefined" || !document.fonts) return;
  const families = ["Inter", "Roboto", "Poppins", "Playfair Display", "JetBrains Mono", "Space Grotesk"];
  for (const family of families) {
    for (const weight of [400, 500, 700]) {
      void document.fonts.load(`${weight} 16px "${family}"`);
    }
  }
}

import type { AABB } from "../geometry/bounds";

export type SnapLine = {
  axis: "x" | "y";
  at: number;
  start: number;
  end: number;
  label?: string;
};

type Guide = { axis: "x" | "y"; offset: number };

export function snapMove(args: {
  box: AABB;
  others: AABB[];
  guides: Guide[];
  threshold: number;
}): { dx: number; dy: number; lines: SnapLine[] } {
  const x = snapAxis(
    "x",
    [args.box.x, args.box.x + args.box.width / 2, args.box.x + args.box.width],
    collect("x", args.others, args.guides),
    args.threshold,
    args.box,
    args.others,
  );
  const y = snapAxis(
    "y",
    [args.box.y, args.box.y + args.box.height / 2, args.box.y + args.box.height],
    collect("y", args.others, args.guides),
    args.threshold,
    args.box,
    args.others,
  );
  return { dx: x.delta, dy: y.delta, lines: [...x.lines, ...y.lines] };
}

function collect(axis: "x" | "y", others: AABB[], guides: Guide[]): number[] {
  const values: number[] = [];
  for (const box of others) {
    if (axis === "x") values.push(box.x, box.x + box.width / 2, box.x + box.width);
    else values.push(box.y, box.y + box.height / 2, box.y + box.height);
  }
  for (const guide of guides) {
    if (guide.axis === axis) values.push(guide.offset);
  }
  return values;
}

function snapAxis(
  axis: "x" | "y",
  edges: number[],
  targets: number[],
  threshold: number,
  moving: AABB,
  others: AABB[],
): { delta: number; lines: SnapLine[] } {
  let best = threshold;
  let delta = 0;
  let at = 0;
  for (const edge of edges) {
    for (const target of targets) {
      const d = target - edge;
      if (Math.abs(d) <= best) {
        best = Math.abs(d);
        delta = d;
        at = target;
      }
    }
  }
  if (best >= threshold && delta === 0 && best === threshold) {
    return { delta: 0, lines: [] };
  }
  if (Math.abs(delta) > threshold) return { delta: 0, lines: [] };
  if (delta === 0 && best === threshold) return { delta: 0, lines: [] };

  const crossStart = axis === "x" ? Math.min(moving.y, ...others.map((o) => o.y)) : Math.min(moving.x, ...others.map((o) => o.x));
  const crossEnd =
    axis === "x"
      ? Math.max(moving.y + moving.height, ...others.map((o) => o.y + o.height))
      : Math.max(moving.x + moving.width, ...others.map((o) => o.x + o.width));
  const gap = nearestGap(axis, moving, others, delta);
  return {
    delta,
    lines: [
      {
        axis,
        at,
        start: Number.isFinite(crossStart) ? crossStart : 0,
        end: Number.isFinite(crossEnd) ? crossEnd : 0,
        label: gap ? `${Math.round(gap)}` : undefined,
      },
    ],
  };
}

function nearestGap(axis: "x" | "y", moving: AABB, others: AABB[], delta: number): number | null {
  const box =
    axis === "x"
      ? { ...moving, x: moving.x + delta }
      : { ...moving, y: moving.y + delta };
  let best: number | null = null;
  for (const other of others) {
    const overlap =
      axis === "x"
        ? intervalsOverlap(box.y, box.y + box.height, other.y, other.y + other.height)
        : intervalsOverlap(box.x, box.x + box.width, other.x, other.x + other.width);
    if (!overlap) continue;
    const gap =
      axis === "x"
        ? box.x >= other.x + other.width
          ? box.x - (other.x + other.width)
          : other.x >= box.x + box.width
            ? other.x - (box.x + box.width)
            : null
        : box.y >= other.y + other.height
          ? box.y - (other.y + other.height)
          : other.y >= box.y + box.height
            ? other.y - (box.y + box.height)
            : null;
    if (gap === null) continue;
    if (best === null || gap < best) best = gap;
  }
  return best;
}

function intervalsOverlap(a0: number, a1: number, b0: number, b1: number): boolean {
  return a0 < b1 && a1 > b0;
}

