+
+const SYNC_COMMON = [
+  "x",
+  "y",
+  "width",
+  "height",
+  "rotation",
+  "opacity",
+  "visible",
+  "locked",
+  "cornerRadius",
+  "fills",
+  "strokes",
+  "effects",
+  "constraintH",
+  "constraintV",
