    {
      bounds: { x: x + hw, y: y + hh, width: hw, height: hh },
      depth: node.depth + 1,
      items: [],
      children: null,
    },
  ];
  const items = node.items;
  node.items = [];
  for (const existing of items) {
    for (const child of node.children) insertInto(child, existing, capacity, maxDepth);
