import { bytesToBase64, base64ToBytes, DocumentSync } from "./collab/sync";
import { aabbOfBox, inflate, unionAabb, type AABB } from "./geometry/bounds";
import { flatten, hitLocal, polygonLocal, starLocal } from "./geometry/hit";
import {
