+    if (!style) return;
+    this.change("Apply color style", (m) => {
+      for (const id of this.selection) {
+        const node = m.node(id);
+        if (!node || !isGeometric(node)) continue;
+        m.remember(id);
+        node.fills = [solidFill({ ...style.color })];
+        node.fillStyleId = style.id;
