      ctx.shadowColor = rgbaCss(drop.color);
      ctx.shadowBlur = drop.blur;
      ctx.shadowOffsetX = drop.x;
      ctx.shadowOffsetY = drop.y;
    }
    ctx.globalAlpha *= fill.opacity;
    ctx.fillStyle = fillStyle(ctx, fill, geom);
