function vectorPath(ctx: CanvasRenderingContext2D, node: Extract<GeometricNode, { type: "vector" }>): void {
  for (const contour of node.contours) {
    const points = contour.points;
    const first = points[0];
    if (!first) continue;
    ctx.moveTo(first.x, first.y);
