  ctx.arcTo(w, 0, w, tr, tr);
  ctx.lineTo(w, h - br);
  ctx.arcTo(w, h, w - br, h, br);
  ctx.lineTo(bl, h);
  ctx.arcTo(0, h, 0, h - bl, bl);
