function setWorld(ctx: CanvasRenderingContext2D, snap: SceneSnapshot, world: Matrix): void {
  const { camera, dpr } = snap;
  const z = camera.zoom;
  ctx.setTransform(
    dpr * z * world.a,
    dpr * z * world.b,
    dpr * z * world.c,
    dpr * z * world.d,
    dpr * (z * world.e + camera.x),
    dpr * (z * world.f + camera.y),
