  return Math.max(0, Math.min(1, n));
}

function getImage(src: string): HTMLImageElement | null {
  let image = images.get(src);
  if (!image) {
    image = new Image();
    image.src = src;
    images.set(src, image);
  }
  return image.complete && image.naturalWidth > 0 ? image : null;
}

