function drawPen(ctx: CanvasRenderingContext2D, editor: Editor): void {
  const pen = editor.ephemeral.pen;
  if (!pen || pen.points.length === 0) return;
  ctx.save();
  ctx.strokeStyle = "#4c7dff";
  ctx.fillStyle = "#ffffff";
  ctx.lineWidth = 1.25;
  ctx.beginPath();
  pen.points.forEach((point, index) => {
