      const world = editor.world.get(id);
      if (geom && world) {
        const anchor = editor.worldToScreen(...pair(apply(world, 0, 0)));
        label(ctx, node.name, anchor.x, anchor.y - 18, node.type === "frame" && node.isComponent ? "#7c5cff" : "#4c7dff");
