      const y = event.clientY - rect.top;
      if (event.ctrlKey || event.metaKey) editor.zoomAt(x, y, editor.camera.zoom * Math.exp(-event.deltaY * 0.0016));
      else editor.panBy(-event.deltaX, -event.deltaY);
